// src/app/services/product.service.ts

import { Observable } from 'rxjs';
import { HttpClient } from '@angular/common/http';
import { Injectable } from '@angular/core';

// L'interface pour la catégorie (pour la lecture seulement, la création utilise juste l'ID)
export interface Categorie {
  id: number;
  nom: string;
}

// L'interface pour le Produit (notez que la catégorie est un objet complet à la lecture)
export interface Produit {
  id: number;
  nom: string;
  prix: number;
  categorie: Categorie; // L'objet catégorie complet
}

@Injectable({
  providedIn: 'root'
})
export class ProductService {
  private apiUrl = 'http://127.0.0.1:8000/api/produits/';

  constructor(private http: HttpClient) { }

  // --- Méthodes Produit (CRUD) ---

  // READ (Liste des produits)
  getProducts(): Observable<Produit[]> {
    return this.http.get<Produit[]>(this.apiUrl);
  }

  // CREATE (Ajouter un produit)
  // L'API attend ici l'ID de la catégorie, pas l'objet complet.
  addProduct(productData: { nom: string; prix: number; categorie: number }): Observable<Produit> {
    return this.http.post<Produit>(this.apiUrl, productData);
  }

  // UPDATE (Modifier un produit)
  updateProduct(product: { id: number; nom: string; prix: number; categorie: number }): Observable<Produit> {
    return this.http.put<Produit>(`${this.apiUrl}${product.id}/`, product);
  }

  // DELETE (Supprimer un produit)
  deleteProduct(id: number): Observable<any> {
    return this.http.delete(`${this.apiUrl}${id}/`);
  }
}
